{
  "design": {
    "theme": "chalk",
    "picture_style": "illustration"
  },
  "flow": [
    {"slide": 1, "does": "Recall French pronouns and numbers", "look_at": {"kind": "none", "shows": null}, "teaches": []},
    {"slide": 2, "does": "Introduce the approved objectives", "look_at": {"kind": "none", "shows": null}, "teaches": []},
    {"slide": 3, "does": "Teach six family nouns with possessives", "look_at": {"kind": "diagram", "shows": "Family members organised around a speaker"}, "teaches": [1]},
    {"slide": 4, "does": "Correct the belief that the speaker determines mon or ma", "look_at": {"kind": "picture", "shows": "A girl referring to her father and mother"}, "teaches": [1]},
    {"slide": 5, "does": "Check possessive choice", "look_at": {"kind": "none", "shows": null}, "teaches": [1]},
    {"slide": 6, "does": "Model name, age and personality sentences", "look_at": {"kind": "picture", "shows": "Two family members described with masculine and feminine forms"}, "teaches": [2]},
    {"slide": 7, "does": "Practise parallel descriptions", "look_at": {"kind": "none", "shows": null}, "teaches": [1, 2]},
    {"slide": 8, "does": "Teach positive and negative sibling sentences", "look_at": {"kind": "diagram", "shows": "Sibling noun phrases after j’ai and je n’ai pas de"}, "teaches": [3]},
    {"slide": 9, "does": "Model a short family paragraph", "look_at": {"kind": "picture", "shows": "A speaker with one sister"}, "teaches": [1, 2, 3]},
    {"slide": 10, "does": "Write a near-identical paragraph from given details", "look_at": {"kind": "none", "shows": null}, "teaches": [1, 2, 3]},
    {"slide": 11, "does": "Write and review an independent family description", "look_at": {"kind": "none", "shows": null}, "teaches": [1, 2, 3]},
    {"slide": 12, "does": "Apply the language to a new speaker and justify choices", "look_at": {"kind": "none", "shows": null}, "teaches": [1, 2, 3]}
  ],
  "title": {
    "template": "title",
    "heading": "Ma famille",
    "lead": "My family\nRappelle-toi / Recall:\nWhat do je, il and elle mean?\nSay 12, 13 and 14 in French.",
    "picture": null
  },
  "slides": [
    {
      "template": "big-visual",
      "heading": "Les objectifs / Learning objectives",
      "lead": null,
      "figure": {
        "kind": "table",
        "shows": "Placeholder replaced by the approved objectives by the lesson renderer",
        "alt": "The approved learning objectives.",
        "title": null,
        "header": null,
        "rows": [
          ["Identify family members"],
          ["Describe name, age and personality"],
          ["Write a short family description"]
        ]
      }
    },
    {
      "template": "big-visual",
      "heading": "Écoute et répète / Listen and repeat",
      "lead": "mon / ma / mes = my",
      "figure": {
        "kind": "labelled-diagram",
        "shows": "An illustrated family map around a central teenage speaker labelled moi. Six separate surrounding panels show a father, mother, brother, sister, the father and mother together, and two grandparents together. Each French label has its English meaning beneath it; the paired panels clearly represent plural nouns.",
        "labels": [
          "moi / me",
          "mon père / father",
          "ma mère / mother",
          "mon frère / brother",
          "ma sœur / sister",
          "mes parents / parents",
          "mes grands-parents / grandparents"
        ]
      }
    },
    {
      "template": "visual-text",
      "heading": "Mon ou ma ? / Which one?",
      "lead": "The French noun decides—not the person speaking.",
      "points": [
        {"label": "Singular", "text": "mon + masculine; ma + feminine"},
        {"label": "Plural", "text": "mes + plural, masculine or feminine"}
      ],
      "figure": {
        "shows": "A teenage girl standing between her father and mother",
        "must_see": ["teenage girl", "adult father", "adult mother"],
        "subject": "generic"
      }
    },
    {
      "template": "hinge",
      "heading": "Choisis / Choose",
      "stem": "A girl says: « ___ père, ___ mère, ___ parents ». Which set fits?",
      "options": [
        "ma, ma, mes",
        "mon, ma, mes",
        "mon, mon, mes",
        "mon, ma, mon"
      ],
      "correct": 2
    },
    {
      "template": "visual-text",
      "heading": "Décrire quelqu’un / Describe someone",
      "lead": "Il / elle = he / she. In French, age uses a: ‘has’.",
      "points": [
        "Mon frère s’appelle Léo. Il a treize ans. Il est gentil et amusant.",
        "Ma sœur s’appelle Léa. Elle a treize ans. Elle est gentille et amusante."
      ],
      "figure": {
        "shows": "Two friendly teenage siblings, a boy and a girl",
        "must_see": ["teenage boy", "teenage girl", "friendly smiles"],
        "subject": "generic"
      }
    },
    {
      "template": "practice",
      "heading": "À toi / Your turn",
      "questions": [
        "Brother: Hugo, 14, kind. Write three sentences: name, age and personality.",
        "Sister: Inès, 12, funny. Write three sentences: name, age and personality."
      ],
      "instruction": "Écris en français / Write in French.\nName: s’appelle • Age: a … ans • Personality: est\nkind: gentil/gentille • funny: amusant/amusante\n12: douze • 14: quatorze",
      "picture": null
    },
    {
      "template": "visual-text",
      "heading": "Frères et sœurs / Siblings",
      "lead": "J’ai = I have. Je n’ai pas de = I don’t have any.",
      "points": [
        "J’ai un frère et deux sœurs. / I have a brother and two sisters.",
        "Je n’ai pas de frère. / I don’t have any brothers."
      ],
      "figure": {
        "kind": "flow",
        "shows": "How a positive sibling phrase changes after a negative expression",
        "alt": "J’ai un frère becomes je n’ai pas de frère; j’ai une sœur becomes je n’ai pas de sœur.",
        "title": null,
        "nodes": [
          "J’ai un frère",
          "Je n’ai pas de frère",
          "J’ai une sœur",
          "Je n’ai pas de sœur"
        ],
        "links": [
          {"from": 0, "to": 1, "label": "negative"},
          {"from": 2, "to": 3, "label": "negative"}
        ]
      }
    },
    {
      "template": "visual-text",
      "heading": "Un petit texte / A short text",
      "lead": "J’ai une sœur. Je n’ai pas de frère.",
      "points": [
        "Ma sœur s’appelle Zoé. Elle a douze ans.",
        "Elle est gentille et amusante."
      ],
      "figure": {
        "shows": "A teenage speaker with one younger sister",
        "must_see": ["teenage speaker", "younger sister", "two smiling faces"],
        "subject": "generic"
      }
    },
    {
      "template": "practice",
      "heading": "À toi / Your turn",
      "questions": [
        "You have one brother and no sisters. Write both sibling sentences.",
        "Your brother is called Sami. He is 13 and kind. Add his name, age and personality."
      ],
      "instruction": "Écris un petit texte / Write a short text.\n13 = treize • kind = gentil/gentille",
      "picture": null
    },
    {
      "template": "practice",
      "heading": "Ma famille / My family",
      "questions": [
        "Write about your own or an imaginary family: say which siblings you have and one sibling type you do not have.",
        "Describe one family member: name, age and one personality trait.",
        "Check mon/ma/mes, il/elle, a … ans and the adjective ending."
      ],
      "instruction": "Écris 5–6 phrases / Write 5–6 sentences.\nHelp: j’ai • je n’ai pas de • s’appelle • a • est\nkind: gentil/gentille • funny: amusant/amusante\nStretch: describe a second family member with a different pronoun.",
      "picture": null
    }
  ]
}
